package pl.osrs;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("osrspopolsku")
public interface PolskiConfig extends Config
{
    @ConfigItem(keyName = "menu", name = "Menu po polsku",
        description = "Tłumaczy rozpoznane opcje po kliknięciu prawym przyciskiem myszy", position = 0)
    default boolean menu()
    {
        return true;
    }

    @ConfigItem(keyName = "napisy", name = "Polskie napisy",
        description = "Wyświetla napisy do rozpoznanych dialogów i tekstów dziennika", position = 1)
    default boolean napisy()
    {
        return true;
    }
}

package pl.osrs;

import com.google.inject.Inject;
import com.google.inject.Provides;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "OSRS po polsku (Korbol)", description = "Polskie opcje menu i napisy do wybranych tekstów gry")
public class PolskiPlugin extends Plugin
{
    @Inject private OverlayManager overlays;
    @Inject private PolskieNapisy napisy;
    @Inject private PolskiConfig config;

    private final Slownik menu = new Slownik("menu.tsv");

    @Provides
    PolskiConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(PolskiConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlays.add(napisy);
    }

    @Override
    protected void shutDown()
    {
        overlays.remove(napisy);
    }

    @Subscribe(priority = -100)
    public void onMenuOpened(MenuOpened event)
    {
        if (!config.menu())
        {
            return;
        }
        // Leave menus in English while other plugins build or reorder them.
        for (MenuEntry entry : event.getMenuEntries())
        {
            String option = entry.getOption();
            String translation = menu.translate(option);
            if (translation != null)
            {
                entry.setOption(Slownik.forGameFont(translation));
            }
        }
    }
}

package pl.osrs;

import com.google.inject.Inject;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.LinkedHashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class PolskieNapisy extends OverlayPanel
{
    private static final Font FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 13);
    private static final int TEXT_WIDTH = 290;
    private static final int[] TEXT_WIDGETS = {
        InterfaceID.ChatLeft.TEXT, InterfaceID.ChatRight.TEXT,
        InterfaceID.Objectbox.TEXT, InterfaceID.Chatmenu.OPTIONS,
        InterfaceID.Questjournal.TITLE, InterfaceID.Questjournal.TEXTLAYER
    };

    private final Client client;
    private final PolskiConfig config;
    private final Slownik texts = new Slownik("teksty.tsv");

    @Inject
    PolskieNapisy(Client client, PolskiConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.napisy())
        {
            return null;
        }

        Set<String> translations = new LinkedHashSet<>();
        for (int componentId : TEXT_WIDGETS)
        {
            collect(client.getWidget(componentId), translations);
        }
        if (translations.isEmpty())
        {
            return null;
        }

        Graphics2D layer = (Graphics2D) graphics.create();
        try
        {
            layer.setFont(FONT);
            getPanelComponent().setPreferredSize(new Dimension(TEXT_WIDTH + 10, 0));
            getPanelComponent().getChildren().add(TitleComponent.builder().text("Tłumaczenie").build());
            FontMetrics metrics = layer.getFontMetrics();
            for (String translation : translations)
            {
                StringBuilder line = new StringBuilder();
                for (String word : translation.split(" "))
                {
                    if (line.length() > 0 && metrics.stringWidth(line + " " + word) > TEXT_WIDTH)
                    {
                        addLine(line.toString());
                        line.setLength(0);
                    }
                    if (line.length() > 0)
                    {
                        line.append(' ');
                    }
                    line.append(word);
                }
                addLine(line.toString());
            }
            return super.render(layer);
        }
        finally
        {
            layer.dispose();
        }
    }

    private void collect(Widget widget, Set<String> translations)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }
        String text = widget.getText();
        if (text != null)
        {
            String plain = text.replace("<br>", " ").replaceAll("<[^>]*>", "");
            String translation = texts.translate(plain);
            if (translation != null)
            {
                translations.add(translation);
            }
        }
        Widget[] children = widget.getChildren();
        if (children != null)
        {
            for (Widget child : children)
            {
                collect(child, translations);
            }
        }
    }

    private void addLine(String text)
    {
        getPanelComponent().getChildren().add(LineComponent.builder().left(text).build());
    }
}

package pl.osrs;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

final class Slownik
{
    private final Map<String, String> translations = new HashMap<>();

    Slownik(String file)
    {
        InputStream stream = Slownik.class.getResourceAsStream(file);
        if (stream == null)
        {
            throw new IllegalStateException("Brak słownika: " + file);
        }
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
        {
            String line;
            int number = 0;
            while ((line = reader.readLine()) != null)
            {
                number++;
                if (line.isBlank() || line.startsWith("#"))
                {
                    continue;
                }
                String[] columns = line.split("\t", -1);
                if (columns.length != 2 || columns[0].isBlank() || columns[1].isBlank()
                    || translations.putIfAbsent(key(columns[0]), columns[1]) != null)
                {
                    throw new IllegalStateException("Nieprawidłowy wpis w " + file + ", wiersz " + number);
                }
            }
        }
        catch (IOException e)
        {
            throw new IllegalStateException("Nie można odczytać " + file, e);
        }
    }

    String translate(String text)
    {
        return text == null ? null : translations.get(key(text));
    }

    private static String key(String text)
    {
        return text.replace('’', '\'').replace('\u00a0', ' ').strip()
            .replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    static String forGameFont(String text)
    {
        return Normalizer.normalize(text, Normalizer.Form.NFD)
            .replaceAll("\\p{M}+", "").replace('ł', 'l').replace('Ł', 'L');
    }
}

package pl.osrs;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public final class Start
{
    private Start() {}

    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(PolskiPlugin.class);
        RuneLite.main(args);
    }
}
